#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const {ACTION,OPERATION,VERSION,FILES,HELPER_SOURCE,HELPER_SHA}=require('./lib/titan-v13-contract');
const {shaBuf,shaFile,atomic,restart,syntax,helperPreflight,snapshot,restore,fail}=require('./lib/titan-v13-runtime');
const {assertKnownBaseline,patchBase,patchExecutor,patchPlugin,patchPolicy,patchPinnedHelpers}=require('./lib/titan-v13-patch');
function candidate(b){if(!fs.existsSync(HELPER_SOURCE))fail('helper_source_missing');const helper=fs.readFileSync(HELPER_SOURCE);if(shaBuf(helper)!==HELPER_SHA)fail('helper_sha_mismatch');const c={base:patchBase(b.source.base),executor:patchExecutor(b.source.executor),plugin:patchPlugin(b.source.plugin),policy:patchPolicy(b.policy),helper};syntax('base',c.base);syntax('executor',c.executor);syntax('plugin',c.plugin,true);JSON.parse(c.policy);syntax('helper',helper.toString('utf8'));const oldPluginSha=b.current_hashes.plugin,newPluginSha=shaBuf(Buffer.from(c.plugin));const pinned=patchPinnedHelpers(oldPluginSha,newPluginSha);for(const x of pinned)syntax('pinned-'+x.file.split('/').pop(),x.new);return {c,pinned,newPluginSha,helper_preflight:helperPreflight(helper,ACTION)}}
function verifyPost(newPluginSha){for(const k of ['base','executor','plugin'])if(!fs.readFileSync(FILES[k],'utf8').includes(ACTION))fail('post_action_missing:'+k);const p=JSON.parse(fs.readFileSync(FILES.policy,'utf8'));if(p.operations?.[OPERATION]?.level!==4)fail('post_policy_operation_missing');if(!p.typed_scopes.some(x=>x&&x.action===ACTION&&x.operation===OPERATION&&x.risk==='critical'))fail('post_policy_scope_missing');if(shaFile(FILES.helper)!==HELPER_SHA)fail('post_helper_sha_mismatch');if(shaFile(FILES.plugin)!==newPluginSha)fail('post_plugin_sha_mismatch');return p}
function main(){const args=process.argv.slice(2);if(args.length>1||(args.length===1&&args[0]!=='--preflight-only'))fail('unexpected_arguments');if(process.getuid&&process.getuid()!==0)fail('must_run_as_root');const b=assertKnownBaseline(),{c,pinned,newPluginSha,helper_preflight}=candidate(b);const candidate_hashes={base:shaBuf(Buffer.from(c.base)),executor:shaBuf(Buffer.from(c.executor)),plugin:newPluginSha,policy:shaBuf(Buffer.from(c.policy)),helper:HELPER_SHA};const report={ok:true,schema_version:'prhm.host-action-bootstrap-preflight.v1',preflight_only:true,action:ACTION,target_version:VERSION,current_hashes:b.current_hashes,candidate_hashes,pinned_helpers:pinned.map(x=>({file:x.file,current_sha256:shaBuf(Buffer.from(x.old)),candidate_sha256:shaBuf(Buffer.from(x.new))})),helper_preflight,database_mutation:false,production_mutation:false,automatic_rollback:true};if(args[0]==='--preflight-only'){process.stdout.write(JSON.stringify(report)+'\n');return}const touched=[FILES.base,FILES.executor,FILES.plugin,FILES.policy,FILES.helper,...pinned.map(x=>x.file)],snap=snapshot(touched);let ok=false;try{atomic(FILES.helper,c.helper,0o755);atomic(FILES.base,c.base,0o755);atomic(FILES.executor,c.executor,0o755);atomic(FILES.plugin,c.plugin,0o644);atomic(FILES.policy,c.policy,0o644);for(const x of pinned)atomic(x.file,x.new,x.mode);const policy=verifyPost(newPluginSha),health=restart();ok=true;process.stdout.write(JSON.stringify({ok:true,schema_version:'prhm.host-action-install-result.v1',installed:true,action:ACTION,version:VERSION,helper_sha256:HELPER_SHA,mcp_plugin_sha256:newPluginSha,approval_policy_version:policy.version,health,backup_dir:snap.dir,database_mutation:false,production_mutation:true,automatic_rollback:true})+'\n')}finally{if(!ok){try{restore(snap);restart();process.stderr.write('automatic rollback: PASS\n')}catch(rb){process.stderr.write('automatic rollback: FAIL:'+String(rb&&rb.stack||rb)+'\n')}}}}
try{main()}catch(e){process.stderr.write(String(e&&e.stack||e)+'\n');process.exit(1)}
